const sellerOrders = `-- name: SellerOrders :many
SELECT id, number, customer_id, customer_name, customer_phone, seller_id, checkout_id, seller_name, latitude,
       longitude, address, state, window_start, window_end, total_vnd, access, cancel_reason, refuse_reason, refuse_note,
       created_at, ready_at, collected_at, cancelled_at, refused_at
FROM order_orders
WHERE seller_id = $1 AND window_start >= $2 AND window_start < $3
ORDER BY window_start, number
LIMIT 500
`

type SellerOrdersParams struct {
	SellerID uuid.UUID
	DayStart time.Time
	DayEnd   time.Time
}

type SellerOrdersRow struct {
	ID            uuid.UUID
	Number        pgtype.Int8
	CustomerID    uuid.NullUUID
	CustomerName  string
	CustomerPhone string
	SellerID      uuid.UUID
	CheckoutID    uuid.UUID
	SellerName    string
	Latitude      float64
	Longitude     float64
	Address       string
	State         string
	WindowStart   time.Time
	WindowEnd     time.Time
	TotalVnd      int64
	Access        string
	CancelReason  string
	RefuseReason  pgtype.Text
	RefuseNote    string
	CreatedAt     time.Time
	ReadyAt       *time.Time
	CollectedAt   *time.Time
	CancelledAt   *time.Time
	RefusedAt     *time.Time
}

// A seller's orders whose window starts within [day_start, day_end), soonest
// first.
func (q *Queries) SellerOrders(ctx context.Context, arg SellerOrdersParams) ([]SellerOrdersRow, error) {
	rows, err := q.db.Query(ctx, sellerOrders, arg.SellerID, arg.DayStart, arg.DayEnd)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SellerOrdersRow
	for rows.Next() {
		var i SellerOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.CustomerID,
			&i.CustomerName,
			&i.CustomerPhone,
			&i.SellerID,
			&i.CheckoutID,
			&i.SellerName,
			&i.Latitude,
			&i.Longitude,
			&i.Address,
			&i.State,
			&i.WindowStart,
			&i.WindowEnd,
			&i.TotalVnd,
			&i.Access,
			&i.CancelReason,
			&i.RefuseReason,
			&i.RefuseNote,
			&i.CreatedAt,
			&i.ReadyAt,
			&i.CollectedAt,
			&i.CancelledAt,
			&i.RefusedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setWindow = `-- name: SetWindow :exec
WITH moved AS (
    UPDATE order_orders SET window_start = $1, window_end = $2
    WHERE id = $3 AND state IN ('confirmed', 'ready')
    RETURNING id, seller_id, state
)
SELECT pg_notify('secondbite_live', json_build_object(
    'topics', json_build_array('order:' || id::text, 'seller:' || seller_id::text),
    'notice', json_build_object('type', 'order', 'orderId', id, 'status', state)
)::text)
FROM moved
`

type SetWindowParams struct {
	WindowStart time.Time
	WindowEnd   time.Time
	ID          uuid.UUID
}

// Moves an order still to collect to a new window, and tells the sockets
// following it (channel secondbite_live); one that ended stays as it was.
func (q *Queries) SetWindow(ctx context.Context, arg SetWindowParams) error {
	_, err := q.db.Exec(ctx, setWindow, arg.WindowStart, arg.WindowEnd, arg.ID)
	return err
}

const unreadOf = `-- name: UnreadOf :many
SELECT c.order_id,
       c.last_seq AS messages,
       (SELECT count(*) FROM order_messages AS m
        WHERE m.order_id = c.order_id AND m.sender = 'seller' AND m.seq > c.customer_seen_seq) AS customer_unread,
       (SELECT count(*) FROM order_messages AS m
        WHERE m.order_id = c.order_id AND m.sender = 'customer' AND m.seq > c.seller_seen_seq) AS seller_unread
FROM order_chats AS c
WHERE c.order_id = ANY ($1::uuid[])
`

type UnreadOfRow struct {
	OrderID        uuid.UUID
	Messages       int32
	CustomerUnread int64
	SellerUnread   int64
}

// For each order with a chat: how many messages it holds, what its customer
// has not read from the seller, and what its seller's people have not read
// from the customer.
func (q *Queries) UnreadOf(ctx context.Context, orderIds []uuid.UUID) ([]UnreadOfRow, error) {
	rows, err := q.db.Query(ctx, unreadOf, orderIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnreadOfRow
	for rows.Next() {
		var i UnreadOfRow
		if err := rows.Scan(
			&i.OrderID,
			&i.Messages,
			&i.CustomerUnread,
			&i.SellerUnread,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
